def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
    opp_d = n - opp_c

    if opp_c == 0:
        return 'D'
    if opp_d == 0:
        return 'C'

    last_me, last_op = history[-1]

    if opp_c <= n // 3:
        if last_me == 'D' and last_op == 'D':
            recent_c = 0
            for i in range(max(0, n - 6), n):
                if history[i][1] == 'C':
                    recent_c += 1
            if recent_c >= 2:
                return 'C'
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    if last_op == 'D':
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    return 'C'
